#include <iostream>
#include <vector>
#include <map>
#include <queue>
#include <bitset>
using namespace std;

inline int upb(int n) {
    return 32 - __builtin_clz(n);
}

int main() {
    bitset<1 << (5 * 5)> close; // Use bitset for memory efficiency
    vector<int> cls(1000000);
    int cls_cnt = 0;

    for (int n; cin >> n, !(n == 0); ) {
        vector<vector<int>> pats(n * n + 1);
        vector<int> tmp(n * n, 0);

        // Optimize pattern generation
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = i; k < n; k++) {
                    for (int l = j; l < n; l++) {
                        fill(tmp.begin(), tmp.end(), 0);
                        for (int a = i; a <= k; a++)
                            for (int b = j; b <= l; b++)
                                tmp[a * n + b] = 1;

                        int bd = 0;
                        for (int a = 0; a < n; a++) {
                            for (int b = 0; b < n; b++) {
                                bd = (bd << 1) | tmp[a * n + b];
                            }
                        }
                        pats[upb(bd)].push_back(bd);
                    }
                }
            }
        }

        int bd = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int t; cin >> t;
                bd = (bd << 1) | t;
            }
        }

        queue<int> mm;
        mm.push(bd);
        close[bd] = true; // Use bitset
        cls[cls_cnt++] = bd;
        while (!mm.empty()) {
            int dep = mm.front() >> 25;
            int cbd = mm.front() & 0x1ffffff;
            mm.pop();

            int ub = upb(cbd);
            const vector<int>& ps = pats[ub];
            for (const auto& p : ps) {
                int nbd = cbd ^ p;
                if (nbd == 0) {
                    for (int i = 0; i <= dep; i++)
                        cout << "myon";
                    cout << endl;
                    goto _exit;
                }
                if (!close[nbd]) {
                    close[nbd] = true;
                    cls[cls_cnt++] = nbd;
                    mm.push(((dep + 1) << 25) | nbd);
                }
            }
        }
    _exit:;
        cls_cnt = 0;
    }
    return 0;
}

